Longest Repeating Character Replacement.source:
import java.util.*;

public class Solution {
  public static int solve(String s, int k) {
    if (k < 0) throw new IllegalArgumentException();
    int[] count = new int[26];
    int l = 0, best = 0;
    for (int r = 0; r < s.length(); r++) {
      int x = s.charAt(r) - 'A';
      if (x < 0 || x >= 26) throw new IllegalArgumentException();
      count[x]++;
      while (true) {
        int max = 0;
        for (int f : count) max = Math.max(max, f);
        if (r - l + 1 - max <= k) break;
        count[s.charAt(l++) - 'A']--;
      }
      best = Math.max(best, r - l + 1);
    }
    return best;
  }

  public static void main(String[] args) {
    System.out.println(solve("AABABBA", 1));
  }
}

Minimum Window Substring.source:
import java.util.*;

public class Solution {
  public static String solve(String s, String t) {
    if (t.isEmpty()) return "";
    int[] need = new int[65536];
    for (char c : t.toCharArray()) need[c]++;
    int missing = t.length(), l = 0, start = 0, best = Integer.MAX_VALUE;
    for (int r = 0; r < s.length(); r++) {
      if (need[s.charAt(r)]-- > 0) missing--;
      while (missing == 0) {
        if (r - l + 1 < best) {
          best = r - l + 1;
          start = l;
        }
        if (++need[s.charAt(l++)] > 0) missing++;
      }
    }
    return best == Integer.MAX_VALUE ? "" : s.substring(start, start + best);
  }

  public static void main(String[] args) {
    System.out.println(solve("ADOBECODEBANC", "ABC"));
  }
}

Minimum Window Subsequence.source:
import java.util.*;

public class Solution {
  public static String solve(String s, String t) {
    if (t.isEmpty()) return "";
    int[] previous = new int[s.length() + 1];
    Arrays.fill(previous, -1);
    for (int i = 1; i <= s.length(); i++)
      previous[i] = s.charAt(i - 1) == t.charAt(0) ? i - 1 : previous[i - 1];
    for (int j = 1; j < t.length(); j++) {
      int[] current = new int[s.length() + 1];
      Arrays.fill(current, -1);
      for (int i = 1; i <= s.length(); i++)
        current[i] =
            s.charAt(i - 1) == t.charAt(j) && previous[i - 1] >= 0
                ? previous[i - 1]
                : current[i - 1];
      previous = current;
    }
    int start = -1, best = Integer.MAX_VALUE;
    for (int i = 1; i <= s.length(); i++)
      if (previous[i] >= 0 && i - previous[i] < best) {
        best = i - previous[i];
        start = previous[i];
      }
    return start < 0 ? "" : s.substring(start, start + best);
  }

  public static void main(String[] args) {
    System.out.println(solve("abcdebdde", "bde"));
  }
}

