import java.util.*;

public class Solution {
  public static long solve(String s) {
    int[] last = {-1, -1, -1};
    long count = 0;
    for (int i = 0; i < s.length(); i++) {
      int x = s.charAt(i) - 'a';
      if (x < 0 || x > 2) throw new IllegalArgumentException();
      last[x] = i;
      count += 1 + Math.min(last[0], Math.min(last[1], last[2]));
    }
    return count;
  }

  public static void main(String[] args) {
    System.out.println(solve("abcabc"));
  }
}

Binary Subarrays With Sum.source:
import java.util.*;

public class Solution {
  private static long atMost(int[] a, int goal) {
    if (goal < 0) return 0;
    int l = 0;
    long sum = 0, ans = 0;
    for (int r = 0; r < a.length; r++) {
      sum += a[r];
      while (sum > goal) sum -= a[l++];
      ans += r - l + 1;
    }
    return ans;
  }

  public static long solve(int[] a, int goal) {
    return atMost(a, goal) - atMost(a, goal - 1);
  }

  public static void main(String[] args) {
    System.out.println(solve(new int[] {1, 0, 1, 0, 1}, 2));
  }
}

